/* Enforce hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #1e1a24;
  --card-bg: #2d2638;
  --border-color: #120e17;
  --pixel-accent: #7ac74c;
  --pixel-accent-dark: #589635;
  --pixel-secondary: #f4d06f;
  --pixel-cancel: #e76f51;
  --text-main: #f7fff7;
  --text-dim: #c5bcd4;
  --shadow-color: #15101a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Courier New", Courier, monospace, monospace;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  image-rendering: pixelated;
}

.app-container {
  width: 100%;
  max-width: 440px;
  margin: auto;
}

.pixel-card {
  background-color: var(--card-bg);
  border: 4px solid var(--border-color);
  box-shadow: 8px 8px 0 var(--shadow-color);
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.card-header {
  text-align: center;
}

.title {
  font-size: 24px;
  letter-spacing: 2px;
  color: var(--pixel-secondary);
  text-shadow: 2px 2px 0 var(--border-color);
  font-weight: 800;
}

.subtitle {
  font-size: 14px;
  color: var(--text-dim);
  margin-top: 4px;
}

.pixel-art-wrapper {
  padding: 8px;
  background-color: var(--border-color);
  border: 4px solid var(--text-dim);
  display: flex;
  align-items: center;
  justify-content: center;
}

#teaCanvas {
  display: block;
  width: 96px;
  height: 96px;
}

.timer-display-box {
  background-color: var(--border-color);
  border: 4px solid var(--pixel-accent);
  padding: 8px 24px;
  width: 100%;
  text-align: center;
}

.timer-digits {
  font-size: 44px;
  font-weight: 900;
  letter-spacing: 4px;
  color: var(--pixel-accent);
  text-shadow: 3px 3px 0 var(--shadow-color);
}

.status-message {
  width: 100%;
  padding: 12px;
  background-color: var(--pixel-secondary);
  color: var(--border-color);
  font-size: 18px;
  font-weight: 900;
  text-align: center;
  text-transform: uppercase;
  border: 3px solid var(--border-color);
  box-shadow: 4px 4px 0 var(--shadow-color);
}

.preset-group {
  border: none;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-label {
  font-size: 14px;
  font-weight: bold;
  color: var(--text-dim);
  letter-spacing: 1px;
  text-align: center;
}

.preset-buttons {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.pixel-btn {
  font-family: inherit;
  font-size: 16px;
  font-weight: 700;
  padding: 10px 14px;
  border: 3px solid var(--border-color);
  cursor: pointer;
  transition: none;
  user-select: none;
  outline: none;
  position: relative;
  background-color: #3f364e;
  color: var(--text-main);
  box-shadow: 4px 4px 0 var(--border-color);
}

.pixel-btn:hover:not(:disabled) {
  background-color: #514563;
}

.pixel-btn:focus-visible {
  outline: 3px dashed var(--pixel-secondary);
  outline-offset: 2px;
}

.pixel-btn:active:not(:disabled) {
  box-shadow: 1px 1px 0 var(--border-color);
  transform: translate(3px, 3px);
}

.preset-btn.active {
  background-color: var(--pixel-secondary);
  color: var(--border-color);
  border-color: var(--border-color);
  box-shadow: 2px 2px 0 var(--border-color);
  transform: translate(2px, 2px);
}

.action-controls {
  display: flex;
  gap: 12px;
  width: 100%;
}

.action-btn {
  flex: 1;
  font-size: 18px;
  padding: 12px;
}

.start-btn {
  background-color: var(--pixel-accent);
  color: var(--border-color);
}

.start-btn:hover:not(:disabled) {
  background-color: #8be058;
}

.cancel-btn {
  background-color: var(--pixel-cancel);
  color: #fff;
}

.cancel-btn:hover:not(:disabled) {
  background-color: #f08267;
}

.pixel-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: 2px 2px 0 var(--border-color);
  transform: none;
}

@media (min-width: 400px) {
  .preset-buttons {
    flex-direction: row;
  }
  .preset-buttons .preset-btn {
    flex: 1;
    padding: 10px 6px;
    font-size: 15px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const timerDisplay = document.getElementById('timerDisplay');
  const readyBanner = document.getElementById('readyBanner');
  const startBtn = document.getElementById('startBtn');
  const cancelBtn = document.getElementById('cancelBtn');
  const presetButtons = document.querySelectorAll('.preset-btn');
  const canvas = document.getElementById('teaCanvas');
  const ctx = canvas.getContext('2d');

  let selectedSeconds = 120;
  let remainingSeconds = 120;
  let timerInterval = null;
  let isRunning = false;
  let steamFrame = 0;
  let animationInterval = null;

  function formatTime(totalSeconds) {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(remainingSeconds);
  }

  function drawPixelTeaCup() {
    const scale = 6;
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Steam colors
    const steamColor = isRunning ? '#ffffff' : '#6f6280';
    ctx.fillStyle = steamColor;

    const steamOffsets = steamFrame % 2 === 0 ? [0, 1] : [1, 0];

    // Steam wisps
    ctx.fillRect((5 + steamOffsets[0]) * scale, 1 * scale, 1 * scale, 2 * scale);
    ctx.fillRect((9 + steamOffsets[1]) * scale, 1 * scale, 1 * scale, 2 * scale);
    ctx.fillRect((6 + steamOffsets[1]) * scale, 3 * scale, 1 * scale, 2 * scale);
    ctx.fillRect((10 + steamOffsets[0]) * scale, 3 * scale, 1 * scale, 2 * scale);

    // Cup base outline & color
    ctx.fillStyle = '#f4d06f';
    ctx.fillRect(4 * scale, 6 * scale, 8 * scale, 6 * scale);
    ctx.fillRect(5 * scale, 12 * scale, 6 * scale, 1 * scale);

    // Tea liquid on top
    ctx.fillStyle = '#7ac74c';
    ctx.fillRect(4 * scale, 6 * scale, 8 * scale, 1 * scale);

    // Handle
    ctx.fillStyle = '#f4d06f';
    ctx.fillRect(12 * scale, 7 * scale, 2 * scale, 4 * scale);
    ctx.fillStyle = '#120e17';
    ctx.fillRect(12 * scale, 8 * scale, 1 * scale, 2 * scale);

    // Saucer
    ctx.fillStyle = '#e76f51';
    ctx.fillRect(2 * scale, 13 * scale, 12 * scale, 2 * scale);
  }

  function startSteamAnimation() {
    if (animationInterval) clearInterval(animationInterval);
    animationInterval = setInterval(() => {
      steamFrame = (steamFrame + 1) % 4;
      drawPixelTeaCup();
    }, 500);
  }

  function stopSteamAnimation() {
    if (animationInterval) {
      clearInterval(animationInterval);
      animationInterval = null;
    }
    drawPixelTeaCup();
  }

  function startTimer() {
    if (isRunning) return;
    isRunning = true;
    readyBanner.hidden = true;
    startBtn.disabled = true;
    cancelBtn.disabled = false;
    presetButtons.forEach(btn => btn.disabled = true);

    startSteamAnimation();

    timerInterval = setInterval(() => {
      if (remainingSeconds > 0) {
        remainingSeconds -= 1;
        updateDisplay();
      }

      if (remainingSeconds <= 0) {
        clearInterval(timerInterval);
        timerInterval = null;
        isRunning = false;
        readyBanner.hidden = false;
        startBtn.disabled = false;
        cancelBtn.disabled = true;
        presetButtons.forEach(btn => btn.disabled = false);
        stopSteamAnimation();
      }
    }, 1000);
  }

  function cancelTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    isRunning = false;
    remainingSeconds = selectedSeconds;
    updateDisplay();
    readyBanner.hidden = true;
    startBtn.disabled = false;
    cancelBtn.disabled = true;
    presetButtons.forEach(btn => btn.disabled = false);
    stopSteamAnimation();
  }

  presetButtons.forEach(button => {
    button.addEventListener('click', () => {
      if (isRunning) return;
      presetButtons.forEach(b => {
        b.classList.remove('active');
        b.setAttribute('aria-pressed', 'false');
      });
      button.classList.add('active');
      button.setAttribute('aria-pressed', 'true');

      selectedSeconds = parseInt(button.dataset.seconds, 10);
      remainingSeconds = selectedSeconds;
      readyBanner.hidden = true;
      updateDisplay();
    });
  });

  startBtn.addEventListener('click', startTimer);
  cancelBtn.addEventListener('click', cancelTimer);

  updateDisplay();
  drawPixelTeaCup();
});
